import {
  format,
  type ConvertibleUnit,
  type FormatOptions,
  type Unit,
} from '@dynatrace-sdk/units';

import type { ColumnDefBase } from '../hooks/useTable/types.js';
import type { DataTableV2DisplayColumnDef } from '../public.api.js';

export type DataTableV2CellFormatter = FormatOptions<Unit, ConvertibleUnit>;
/**
 * Defines the options passed to the format function.
 */
export type DataTableV2CellFormatterColumnDef = {
  formatter?: DataTableV2CellFormatter;
};

/**
 * Function that formats the cell value based on the formatter specified in the column definition
 * @param column - column definition prop
 *
 * @returns the formatted cell value
 */
function formatColumnCell<TData, TValue>(
  column: DataTableV2DisplayColumnDef<TData, TValue>,
) {
  return ({ getValue }) => format(Number(getValue()), column.formatter);
}

/**
 * Updates the cell renderer with the formatter from the column definition
 * @param column - column definition prop
 *
 * @returns the column definition with the formatter applied
 */
export function applyColumnFormatters<TData, TValue>(
  column: DataTableV2DisplayColumnDef<TData, TValue>,
): { cell?: ColumnDefBase<TData, TValue>['cell'] } {
  if (column.formatter === undefined) {
    return {};
  }

  if (column.formatter) {
    column.cell = formatColumnCell(column) as ColumnDefBase<
      TData,
      TValue
    >['cell'];
  }

  return { cell: column.cell };
}
